  // Logika spec var representing port state for outgoing data port
  @spec var authorization: Factory_Flow.AuthorizationFact = $

  def put_authorization(value : Factory_Flow.AuthorizationFact) : Unit = {
    Contract(
      Modifies(authorization),
      Ensures(
        authorization == value
      )
    )
    Spec {
      authorization = value
    }

    Art.putValue(authorization_Id, Factory_Flow.AuthorizationFact_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var reasonToStatus: Factory_Flow.DecisionReason.Type = $

  def put_reasonToStatus(value : Factory_Flow.DecisionReason.Type) : Unit = {
