        reasonToStatus == value
      )
    )
    Spec {
      reasonToStatus = value
    }

    Art.putValue(reasonToStatus_Id, Factory_Flow.DecisionReason_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

